@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck extends Vehicle {
  + Weight : float
}

class Car extends Vehicle {
  + NumberOfSeats : int
}

class Van extends Vehicle {
}

class Order {
  + Origin : Location
  + Destination : Location
  + DateOfExecution : date
}

Location "1" *-- "*" Driver
Location "1" *-- "*" Vehicle
Driver "1" -- "0..1" Order : carries out
Driver "0..1" -- "*" Vehicle : drives
Order "*" -- "1..*" Driver : assigned to
@enduml

